UPDATE companies SET description='Founded over 30 years ago in Omaha, Nebraska, Sloan Medical is a family-owned business started by urologist Stewart Sloan. The company began with a surgeon’s perspective on protective equipment, aiming to create PPE that addresses the real challenges of the operating room.

All products are designed and produced in North America, with each item undergoing ASTM F1671 viral penetration resistance testing. The company emphasizes one-size-fits-all designs to simplify inventory, and most stocked items ship within 24 hours. The product range excludes gloves, masks, respirators, and face shields.

The primary customers are hospitals, surgical centers, and veterinary facilities across the United States. Surgeons, circulating nurses, OR technicians, and veterinary professionals use the PPE. The company also sells through distributors such as American Medical Depot, Bowers Medical Supply, Healthmark Industries, and Medline Industries.

Sloan Medical differentiates itself through surgeon-led design, North American manufacturing that avoids overseas supply-chain delays, and a commitment to personalized service without requiring customers to go through sales representatives. The non-skid tread integrated into footwear covers and the single-use transfer sheets that eliminate cleaning chemicals are cited as key safety and efficiency features.', certifications=ARRAY['ASTM F1671']::text[], profile='{"capabilities": ["PPE design and manufacturing", "ASTM F1671 viral penetration resistance testing", "North American manufacturing", "24-hour shipping on stocked items", "One-size-fits-all garment design", "Non-skid tread integration", "Disposable single-use patient transfer sheets", "Free sample program", "EDI ordering capability", "Distributor network management"], "industries": ["Healthcare", "Hospitals", "Surgical centers", "Veterinary medicine", "Veterinary education", "Nursing facilities", "Postmortem care"], "materials": [], "equipment": [], "volume": "", "lead_time": "Most products ship within 24 hours", "tolerances": "", "built_on": ["Designed by surgeons for real surgical needs", "ASTM F1671 viral penetration resistance testing on all disposable PPE", "Manufactured in North America with most products shipping within 24 hours", "One-size-fits-all garments reduce inventory to a single SKU", "Non-skid tread built into footwear covers to prevent falls"], "facts_used": ["Founded over 30 years ago -> /", "Family-owned -> /", "Founder Stewart Sloan, urologist -> /about", "Headquarters Omaha, Nebraska -> db", "Manufactures Sta-Dri PPE and ezGLIDE transfer sheets -> /", "All products designed and manufactured in North America -> /", "ASTM F1671 viral penetration resistance testing -> /", "One-size-fits-all design reduces inventory to single SKU -> /", "Most products ship within 24 hours -> /", "Non-skid tread built into plastic to prevent falls -> /", "Disposable single-use patient transfer sheets eliminate cleaning products -> /", "Primary customers: hospitals, surgical centers, veterinary facilities -> /", "Distributors: American Medical Depot, Bowers Medical Supply, Healthmark Industries, Medline Industries -> /", "Does not manufacture gloves, masks, respirators, face shields -> /", "Free samples available -> /", "EDI ordering -> /", "Core values: Excellence, Integrity, Safety, Confidence -> /about", "Leadership team listed -> /about"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "At Sloan Medical, our goal is simple: Manufacture the highest quality personal protective equipment for medical professionals.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='sloan-medical' AND approved AND profile IS NULL;
UPDATE companies SET description='Smart Wave Solar is a locally owned and operated solar installation company based in Denver, Colorado, serving homeowners across Utah and Colorado. The company was founded with a focus on providing turnkey residential solar and battery backup systems without subcontracting installation work.

The firm designs and installs photovoltaic systems paired with battery storage, notably as a certified installer for the Tesla Powerwall 3. Its in-house teams handle every phase of a project—from initial site assessment and system design through permitting, installation, and final inspection—using what it describes as technology and products. The company backs its installations with a 25-year production warranty guaranteeing system output.

Smart Wave Solar serves residential customers exclusively, with a track record of thousands of installations in Utah. The typical client is a homeowner seeking to reduce electricity bills, gain backup power during grid outages, and increase property value.

The company distinguishes itself by refusing to subcontract installations, maintaining direct control over workmanship and project communication. Its installers hold what the firm calls the highest industry credentials, and its sales process emphasizes transparency and education over pressure tactics. The Tesla Powerwall certification allows it to offer whole-home backup that functions during grid failures, a capability the company notes most solar-only systems lack.', certifications=ARRAY['Tesla Powerwall Certified Installer']::text[], profile='{"capabilities": ["Solar photovoltaic system design", "Solar panel installation", "Battery energy storage system installation", "Tesla Powerwall 3 installation", "Project management and permitting", "Financing consultation"], "industries": ["Residential solar energy", "Solar installation services", "Renewable energy"], "materials": ["Photovoltaic modules", "Lithium-ion battery storage (Tesla Powerwall 3)"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Does not subcontract installations; all work performed by in-house teams", "Certified installer for Tesla Powerwall 3 whole-home battery backup", "25-year production warranty guaranteeing system output", "Locally owned and operated in Denver, Colorado", "Handles projects from design through permitting to final inspection"], "facts_used": ["Headquarters in Denver, Colorado -> /", "Locally owned and operated, no subcontracting -> /", "Certified installer for Tesla Powerwall 3 -> /", "25-year production warranty on system output -> /", "Serves residential customers in Utah and Colorado -> /", "Thousands of installations in Utah -> /", "In-house teams handle design, permitting, installation, inspection -> /", "Installers hold highest industry credentials -> /", "Offers financing consultation -> /"], "company_type": "Installer / service company", "makes_products": "no", "type_evidence": "Solar Panels, Batteries and Installation in Utah & Colorado", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='smart-wave-solar' AND approved AND profile IS NULL;
